  /* ---------- 900px以下（縦並び） ---------- */
  @media screen and (max-width: 1023px) {
    .implant-cta__feature {
      padding: 22px 16px;

      &::after {
        inset: 0 0 auto;
        width: auto;
        height: 1px;
