/* ========================================
   インプラントLP：PREVENTION（インプラントは、残った歯を守る治療）
   ・ブリッジ／インプラント の動画2本（WHY NOW と同じ動画のしくみ）
   ・サムネイル：img/implant-lp-prevention-video01・02.webp（入れると表示）
======================================== */

.implant-prevention {
  position: relative;
  padding: 40px 0 40px;
  background:
    radial-gradient(ellipse 40% 50% at 0% 100%, rgba(226, 214, 246, 0.6) 0%, rgba(226, 214, 246, 0) 100%),
    radial-gradient(ellipse 35% 45% at 100% 0%, rgba(226, 230, 250, 0.7) 0%, rgba(226, 230, 250, 0) 100%),
    linear-gradient(180deg, #FCFBFF 0%, #F4F1FA 100%);
  color: $ilp-text;

  &__inner {
    max-width: 1160px;
    margin: 0 auto;
    padding: 0 40px;
  }

  /* ---------- 見出し ---------- */
  &__head {
    text-align: center;
  }

  &__en {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 16px;
    font-family: $ilp-en;
    font-size: 15px;
    font-weight: 600;
    line-height: 1;
    letter-spacing: 0.42em;
    color: #8A6A2E;

    &::after {
      margin-left: -0.42em;
    }

    &::before,
    &::after {
      content: "";
      flex-shrink: 0;
      width: 44px;
      height: 1px;
      background: $ilp-gold-line;
    }
  }

  // h2（英字ラベル＋タイトル）
  &__title {
    margin: 0;
    font-weight: 400;
  }

  &__title-main {
    display: block;
    margin-top: 22px;
    font-family: $ilp-serif;
    font-size: 35px;
    font-weight: 600;
    line-height: 1.5;
    letter-spacing: 0.08em;
    color: $ilp-navy;
  }

  &__ornament {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    margin-top: 12px;

    &::before,
    &::after {
      content: "";
      width: 40px;
      height: 1px;
      background: $ilp-gold-line;
    }
  }

  &__diamond {
    width: 7px;
    height: 7px;
    background: $ilp-gold;
    transform: rotate(45deg);
  }

  /* ---------- 白いカード ---------- */
  &__card {
    margin-top: 28px;
    padding: 24px 56px 22px;
    background: #fff;
    box-shadow: 0 18px 40px rgba(42, 34, 80, 0.09);
  }

  &__compare {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    gap: 24px;
    align-items: start;
  }

  &__col {
    margin: 0;
    padding-top: 14px;

    // インプラント側（ベージュの背景）
    &.is-highlight {
      margin-top: 0;
      padding: 14px 14px 18px;
      border-radius: 6px;
      background: #F7F3EA;
    }
  }

  /* ---------- 動画 ---------- */
  &__video-frame {
    position: relative;
    overflow: hidden;
    aspect-ratio: 472 / 233;
    border-radius: 4px;
    background: radial-gradient(ellipse 70% 80% at 50% 35%, #4A4172 0%, #1E1840 80%);

    &::after {
      content: "";
      position: absolute;
      inset: 55% 0 0;
      z-index: 1;
      background: linear-gradient(180deg, rgba(30, 24, 64, 0) 0%, rgba(30, 24, 64, 0.75) 100%);
      pointer-events: none;
    }

    iframe {
      position: absolute;
      inset: 0;
      z-index: 3;
      width: 100%;
      height: 100%;
      border: 0;
    }

    &.is-playing::after {
      display: none;
    }
  }

  &__col.is-highlight &__video-frame {
    aspect-ratio: 444 / 233;
  }

  &__video-thumb {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  &__video-play {
    position: absolute;
    top: 50%;
    left: 50%;
    z-index: 2;
    width: 65px;
    height: 65px;
    padding: 0;
    border: 0;
    background: $ilp-navy;
    box-shadow: 0 12px 28px rgba(20, 14, 40, 0.35);
    transform: translate(-50%, -50%);
    cursor: pointer;
    transition: background-color 0.3s, transform 0.3s;

    &::before {
      content: "";
      position: absolute;
      inset: 4px;
      border: 1px solid rgba(205, 174, 110, 0.8);
    }

    &:hover:not(:disabled) {
      background: #3A3168;
      transform: translate(-50%, -50%) scale(1.05);
    }

    &:disabled {
      cursor: default;
    }
  }

  &__video-play-icon {
    position: absolute;
    top: 50%;
    left: 50%;
    width: 14px;
    height: 16px;
    background: #D9BC80;
    clip-path: polygon(0 0, 100% 50%, 0 100%);
    transform: translate(-40%, -50%);
  }

  &__video-caption {
    position: absolute;
    left: 22px;
    right: 22px;
    bottom: 12px;
    z-index: 2;
    display: flex;
    align-items: center;
    gap: 12px;
    font-family: $ilp-sans;
    font-size: 12.5px;
    line-height: 1.5;
    letter-spacing: 0.08em;
    color: #fff;
    pointer-events: none;
  }

  &__video-caption-icon {
    position: relative;
    flex-shrink: 0;
    width: 14px;
    height: 11px;
    border: 1px solid #fff;

    &::after {
      content: "";
      position: absolute;
      top: 50%;
      left: 50%;
      width: 4px;
      height: 5px;
      background: #fff;
      clip-path: polygon(0 0, 100% 50%, 0 100%);
      transform: translate(-40%, -50%);
    }
  }

  &__video-frame.is-playing &__video-play,
  &__video-frame.is-playing &__video-caption,
  &__video-frame.is-playing &__video-thumb {
    display: none;
  }

  /* ---------- ブリッジ／インプラント ---------- */
  &__col-body {
    display: block;
  }

  &__col-title {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-top: 16px;
    font-family: $ilp-serif;
    font-size: 18px;
    font-weight: 600;
    line-height: 1.5;
    letter-spacing: 0.12em;
    color: $ilp-navy;

    img {
      display: block;
      flex-shrink: 0;
      width: 24px;
      height: 24px;
    }
  }

  &__col-text {
    display: block;
    margin-top: 12px;
    font-family: $ilp-sans;
    font-size: 13px;
    font-weight: 400;
    line-height: 1.85;
    letter-spacing: 0.04em;
    color: $ilp-text;
  }

  /* ---------- POINT ---------- */
  &__point {
    margin-bottom: 0;
    display: flex;
    align-items: center;
    gap: 18px;
    margin-top: 14px;
  }

  &__point-label {
    flex-shrink: 0;
    padding: 6px 14px;
    background: $ilp-navy;
    font-family: $ilp-en;
    font-size: 13px;
    font-weight: 600;
    line-height: 1.3;
    letter-spacing: 0.25em;
    color: #DCC28C;
  }

  &__point-text {
    font-family: $ilp-serif;
    font-size: 19px;
    font-weight: 500;
    line-height: 1.5;
    letter-spacing: 0.1em;
    color: $ilp-navy;
  }

  // SPだけの要素
  &__mark,
  &__sp,
  &__pair,
  &__br-sp {
    display: none;
  }

  &__summary {
    margin-top: 12px;
    padding: 22px 28px;
    border-radius: 6px;
    background: $ilp-navy;
    font-family: $ilp-sans;
    font-size: 14px;
    font-weight: 700;
    line-height: 1.85;
    letter-spacing: 0.06em;
    color: #fff;
  }

  /* ---------- タブレット ---------- */
  @media screen and (max-width: 1100px) {
    &__card {
      padding: 24px 32px 22px;
    }
  }

  @media screen and (max-width: 1023px) {
    &__compare {
      grid-template-columns: 1fr;
    }

    &__col.is-highlight &__video-frame {
      aspect-ratio: 472 / 233;
    }
  }

  /* ---------- SP ---------- */
  @media screen and (max-width: 1023px) {
    padding: 36px 0 40px;
    background: linear-gradient(180deg, #FAF8F3 0%, #F5F1E8 100%);

    &__inner {
      padding: 0 20px;
    }

    &__br-sp {
      display: inline;
    }

    &__pc,
    &__col-title img {
      display: none;
    }

    &__sp {
      display: inline;
    }

    &__en {
      gap: 12px;
      font-size: 13px;
      letter-spacing: 0.3em;

      &::after {
        margin-left: -0.3em;
      }

      &::before,
      &::after {
        width: 28px;
      }
    }

    // インプラントは、／残った歯を守る治療
    &__title-main {
      margin-top: 14px;
      font-size: 21px;
      line-height: 1.55;
      letter-spacing: 0.06em;
    }

    // 白いカードはなし（比較は背景の上に直接、POINT だけ白い箱）
    &__card {
      margin-top: 22px;
      padding: 0;
      background: none;
      box-shadow: none;
    }

    // ブリッジ／インプラント を横に2列
    &__compare {
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 9px;
    }

    &__col,
    &__col.is-highlight {
      padding: 0;
      border-radius: 0;
      background: none;
    }

    // インプラント側の動画は金の枠
    &__video {
      border: 2px solid transparent;
    }

    &__col.is-highlight &__video {
      border-color: #D9BC7E;
    }

    &__video-frame,
    &__col.is-highlight &__video-frame {
      aspect-ratio: 160 / 92;
      border-radius: 0;
    }

    &__video-play {
      width: 30px;
      height: 30px;

      &::before {
        inset: 2px;
      }
    }

    &__video-play-icon {
      width: 7px;
      height: 8px;
    }

    &__video-caption {
      left: 4px;
      right: 2px;
      bottom: 3px;
      gap: 4px;
      font-size: 6.5px;
      letter-spacing: 0;
      white-space: nowrap;
    }

    &__video-caption-icon {
      width: 7px;
      height: 6px;

      &::after {
        width: 2px;
        height: 3px;
      }
    }

    &__col-title {
      gap: 8px;
      margin-top: 12px;
      font-size: 16px;
      letter-spacing: 0.06em;
    }

    // ×（灰色の枠）／○（紺の四角）
    // 見本：14×14の枠（×は Noto Serif JP 600／10px／#5C566B、枠線 #9C96A8）
    // 文字の上下のずれをなくすため、行の高さを枠と同じにして真ん中に置く
    &__mark {
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      box-sizing: border-box;
      width: 14px;
      height: 14px;
      border: 1px solid #9C96A8;
      font-family: $ilp-serif;
      font-size: 10px;
      font-weight: 600;
      line-height: 12px;
      letter-spacing: 0;
      text-align: center;
      color: #5C566B;
      // 見出しの文字の真ん中にそろえる（和文は少し上寄りに見えるので1px上げる）
      position: relative;
      top: -1px;
    }

    // ○：紺の四角に金の文字（#F0DDAE）
    &__col.is-highlight &__mark {
      border-color: $ilp-navy;
      background: $ilp-navy;
      color: #F0DDAE;
    }

    // 見本：Noto Sans JP 400／10.5px／行間16.8px／字間0.42px／#5C566B
    &__col-text {
      margin-top: 6px;
      font-size: 10.5px;
      line-height: 16.8px;
      letter-spacing: 0.04em;
      color: #5C566B;
    }

    // POINT：白い箱（上に金のタブ）
    &__point-box {
      position: relative;
      margin-top: 40px;
      padding: 30px 16px 20px;
      background: #fff;
      box-shadow: 0 16px 30px rgba(42, 34, 80, 0.14);
      text-align: center;
    }

    &__point {
      position: static;
      display: block;
      margin-top: 0;
    }

    // 見本：92×26 の金のタブ。箱の上の線にまたがる（半分が箱の外）
    &__point-label {
      position: absolute;
      top: -13px;
      left: 50%;
      z-index: 1;
      display: flex;
      align-items: center;
      justify-content: center;
      box-sizing: border-box;
      width: 92px;
      height: 26px;
      padding: 0 0 0 0.25em; // 字間の分だけ右にずらして中央に見せる
      line-height: 1;
      background: $ilp-gold-shine;
      font-size: 13px;
      letter-spacing: 0.25em;
      color: $ilp-navy;
      transform: translateX(-50%);
    }

    &__point-text {
      display: block;
      font-size: 16px;
      line-height: 1.6;
      letter-spacing: 0.06em;
    }

    // “予防歯科” を大きく、下にマーカー
    &__point-big {
      display: inline-block;
      margin-top: 6px;
      font-size: 28px;
      font-weight: 600;
      line-height: 1.3;
      letter-spacing: 0.04em;
      background: linear-gradient(180deg, transparent 62%, rgba(217, 188, 126, 0.45) 62%);
    }

    // 失った歯を補う治療 ／ これ以上、歯を失わないための治療
    &__pair {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 6px;
      margin-top: 14px;
    }

    // 2つの箱は同じ文字設定（高さもそろう）
    // 下の行：Noto Serif JP 600／14px／行間25.9px／字間0.42px
    // 上の行：Noto Sans JP 400／10.5px／行間19.42px／字間0.42px
    &__pair-box {
      display: flex;
      flex-direction: column;
      justify-content: center;
      margin: 0;
      padding: 10px 4px 11px;
      background: #F3EFFA;
      font-family: $ilp-serif;
      font-size: 14px;
      font-weight: 600;
      line-height: 25.9px;
      letter-spacing: 0.03em;
      color: #2A2250;

      span {
        display: block;
        font-family: $ilp-sans;
        font-size: 10.5px;
        font-weight: 400;
        line-height: 19.42px;
        letter-spacing: 0.04em;
        color: #5C566B;
      }

      &.is-dark {
        background: linear-gradient(180deg, #3A2F7A 0%, #2A2250 100%);
        color: #F0DDAE;

        span {
          color: #F0DDAE;
        }
      }
    }

    // まとめの文：紺の帯ではなく、グレーの文
    &__summary {
      margin-top: 12px;
      padding: 0;
      border-radius: 0;
      background: none;
      // 見本：Noto Sans JP 400／11px／行間18.7px／字間0.42px／#5C566B／中央
      font-size: 11px;
      font-weight: 400;
      line-height: 18.7px;
      letter-spacing: 0.038em;
      text-align: center;
      color: #5C566B;
    }
  }
}

/* ========================================
   インプラントLP：REASON（富士見台さくら歯科のインプラントが選ばれる理由）
   ・写真＋右下にずらした金の枠／文章（左右交互）
======================================== */

.implant-reason {
  position: relative;
  padding: 64px 0 90px;
  background: #FBF8F2 var(--reason-bg) center top / 100% 100% no-repeat; // 背景画像をセクション全体に合わせて伸ばす
  color: $ilp-text;

  &__inner {
    max-width: 1160px;
    margin: 0 auto;
    padding: 0 40px;
  }

  /* ---------- 見出し ---------- */
  &__head {
    text-align: center;
  }

  &__en {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 16px;
    font-family: $ilp-en;
    font-size: 14px;
    font-weight: 600;
    line-height: 1;
    letter-spacing: 0.42em;
    color: #8A6A2E;

    &::after {
      margin-left: -0.42em;
    }

    &::before,
    &::after {
      content: "";
      flex-shrink: 0;
      width: 44px;
      height: 1px;
      background: $ilp-gold-line;
    }
  }

  // h2（英字ラベル＋タイトル）
  &__title {
    margin: 0;
    font-weight: 400;
  }

  &__title-main {
    display: block;
    margin-top: 20px;
    font-family: $ilp-serif;
    font-size: 34px;
    font-weight: 600;
    line-height: 1.6;
    letter-spacing: 0.1em;
    color: $ilp-navy;
  }

  &__ornament {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    margin-top: 14px;

    &::before,
    &::after {
      content: "";
      width: 40px;
      height: 1px;
      background: $ilp-gold-line;
    }
  }

  &__diamond {
    width: 7px;
    height: 7px;
    background: $ilp-gold;
    transform: rotate(45deg);
  }

  /* ---------- 理由 01〜05 ---------- */
  &__list {
    margin-top: 92px;
    list-style: none;
  }

  &__item {
    display: grid;
    grid-template-columns: 460px minmax(0, 1fr);
    gap: 56px;
    align-items: center;

    & + & {
      margin-top: 126px;
    }

    // 文章を左、写真を右に
    &.is-reverse {
      grid-template-columns: minmax(0, 1fr) 460px;

      .implant-reason__media {
        order: 2;
        margin: 0 0 14px 14px;

        &::before {
          left: -14px;
          right: 14px;
        }
      }
    }
  }

  // 写真（右下にずらした金の枠）
  &__media {
    position: relative;
    margin: 0 14px 14px 0;

    &::before {
      content: "";
      position: absolute;
      top: 14px;
      left: 14px;
      right: -14px;
      bottom: -14px;
      border: 1px solid #C2A061;
    }

    img {
      position: relative;
      display: block;
      width: 100%;
      height: auto;
    }
  }

  &__body {
    max-width: 560px;
  }

  // 「REASON」は数字の下の線（ベースライン）にそろえる
  &__label {
    margin: 0;
    display: flex;
    align-items: baseline;
    gap: 16px;
  }

  &__label-en {
    font-family: $ilp-en;
    font-size: 12px;
    font-weight: 600;
    line-height: 1;
    letter-spacing: 0.3em;
    color: #8A6A2E;
  }

  // 見本：Cormorant Garamond 500 italic／68px／行間68px／字間0／#9A7836 → #7E6128
  &__num {
    font-family: $ilp-en;
    font-size: 68px;
    font-style: italic;
    font-weight: 500;
    line-height: 68px;
    letter-spacing: 0;
    color: #7E6128;

    @supports ((-webkit-background-clip: text) or (background-clip: text)) {
      background: linear-gradient(180deg, #9A7836 0%, #7E6128 100%);
      -webkit-background-clip: text;
      background-clip: text;
      color: transparent;
    }
  }

  &__badge {
    align-self: flex-start;
    margin-top: 6px;
    padding: 3px 10px;
    background: $ilp-navy;
    font-family: $ilp-sans;
    font-size: 11.5px;
    font-weight: 700;
    line-height: 1.6;
    letter-spacing: 0.06em;
    color: #E2CB98;
  }

  &__item-title {
    margin: 8px 0 0;
    font-family: $ilp-serif;
    font-size: 26px;
    font-weight: 600;
    line-height: 1.6;
    letter-spacing: 0.08em;
    color: $ilp-navy;
  }

  // 本文＋下の金の短い線（Figma：48×2px）
  &__item-text {
    position: relative;
    margin-top: 18px;
    padding-bottom: 30px;
    font-family: $ilp-sans;
    font-size: 14.5px;
    font-weight: 400;
    line-height: 2.05;
    letter-spacing: 0.04em;
    color: #4F4A5E;

    &::after {
      content: "";
      position: absolute;
      left: 0;
      bottom: 0;
      width: 48px;
      height: 2px;
      background: $ilp-gold-line;
    }
  }

  /* ---------- タブレット ---------- */
  @media screen and (max-width: 1100px) {
    &__item,
    &__item.is-reverse {
      gap: 40px;
    }

    &__item {
      grid-template-columns: 380px minmax(0, 1fr);
    }

    &__item.is-reverse {
      grid-template-columns: minmax(0, 1fr) 380px;
    }

    &__item-title {
      font-size: 22px;
    }
  }

  @media screen and (max-width: 900px) {
    &__item,
    &__item.is-reverse {
      grid-template-columns: 1fr;
      gap: 28px;

      .implant-reason__media {
        order: 0;
        width: calc(100% - 14px);
        max-width: 560px;
        margin: 0 auto 14px;

        &::before {
          left: 14px;
          right: -14px;
        }
      }
    }

    &__item + &__item {
      margin-top: 72px;
    }

    &__body {
      max-width: none;
    }
  }

  &__br-sp {
    display: none;
  }

  /* ---------- SP ---------- */
  @media screen and (max-width: 767px) {
    padding: 56px 0;
    // 見本：SPの背景 #FAF8FC → #F2EEF8（背景画像なし）
    background: linear-gradient(180deg, #FAF8FC 0%, #F2EEF8 100%);

    &__inner {
      padding: 0 20px;
    }

    &__br-sp {
      display: inline;
    }

    &__en {
      gap: 12px;
      font-size: 13px;
      letter-spacing: 0.3em;

      &::after {
        margin-left: -0.3em;
      }

      &::before,
      &::after {
        width: 28px;
      }
    }

    // 富士見台さくら歯科の／インプラントが／選ばれる理由
    &__title-main {
      margin-top: 14px;
      font-size: 21px;
      line-height: 1.6;
      letter-spacing: 0.06em;
    }

    &__list {
      margin-top: 28px;
    }

    // 写真は横いっぱい（金の枠なし）
    &__item,
    &__item.is-reverse {
      gap: 16px;

      .implant-reason__media {
        width: 100%;
        max-width: none;
        margin: 0;

        &::before {
          display: none;
        }
      }
    }

    &__item + &__item {
      margin-top: 36px;
    }

    &__label {
      gap: 8px;
    }

    &__label-en {
      font-size: 14px;
      letter-spacing: 0.2em;
    }

    // 見本：Noto Serif JP 600／30px／行間30px／字間0.42px／#B8975A
    &__num {
      font-family: $ilp-serif;
      font-size: 30px;
      font-style: normal;
      font-weight: 600;
      line-height: 30px;
      letter-spacing: 0.014em;
      color: #B8975A;

      @supports ((-webkit-background-clip: text) or (background-clip: text)) {
        background: none;
        -webkit-background-clip: border-box;
        background-clip: border-box;
        color: #B8975A;
      }
    }

    &__badge {
      align-self: center;
      margin: 0 0 0 6px;
      padding: 2px 10px;
      font-size: 11px;
      font-weight: 500;
    }

    &__item-title {
      margin-top: 10px;
      font-size: 17px;
      line-height: 1.6;
      letter-spacing: 0.04em;
    }

    // 下の金の線なし
    &__item-text {
      margin-top: 8px;
      padding-bottom: 0;
      font-size: 12.5px;
      line-height: 1.75;

      &::after {
        display: none;
      }
    }
  }
}

/* ========================================
   インプラントLP：CTA（大きなタイトル：'large' => true）
   ・入れる時も、その先の人生も。最期まで、あなたのお口を守り続けます。
======================================== */

.implant-cta--large {
  padding: 66px 0 70px;

  .implant-cta__en {
    font-size: 14px;
  }

  .implant-cta__title {
    margin-top: 28px;
    font-size: 36px;
    font-weight: 600;
    line-height: 1.6;
    letter-spacing: 0.1em;
  }

  // —— 笑顔、めぐる。富士見台さくら歯科
  .implant-cta__tagline {
    margin-top: 16px;
    font-family: $ilp-serif;
    font-size: 15px;
    font-weight: 500;
    line-height: 1.6;
    letter-spacing: 0.2em;
    color: #8A6A2E;
  }

  .implant-cta__features {
    margin-top: 44px;
  }

  @media screen and (max-width: 1100px) {
    .implant-cta__title {
      font-size: 30px;
    }
  }

  @media screen and (max-width: 1023px) {
    padding: 52px 0 56px;

    .implant-cta__title {
      margin-top: 18px;
      font-size: 19px;
      letter-spacing: 0.03em;
    }

    .implant-cta__tagline {
      margin-top: 12px;
      font-size: 12.5px;
      letter-spacing: 0.08em;
    }

    .implant-cta__features {
      margin-top: 28px;
    }
  }
}

/* ========================================
   インプラントLP：FLOW（インプラント治療の流れ）
   ・背景：img/implant-lp-flow-bg.webp（PHP の style="--flow-bg"）
   ・即時埋入の比較（グリッドで「被せ物」の位置をそろえる）／STEP一覧／STEP 01〜08
======================================== */

.implant-flow {
  position: relative;
  padding: 58px 0 90px;
  background: #FBF8F2 var(--flow-bg) center top / 100% 100% no-repeat;
  color: $ilp-text;

  &__inner {
    max-width: 1160px;
    margin: 0 auto;
    padding: 0 40px;
  }

  /* ---------- 見出し ---------- */
  // 並び：PCは 英字 → チップ → タイトル → ◆（チップはh2の外なので h2 をほどいて並べ替え）
  &__head {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
  }

  &__heading {
    display: contents;
  }

  &__en {
    display: flex;
    align-items: center;
    justify-content: center;
    order: 1;
    gap: 16px;
    font-family: $ilp-en;
    font-size: 14px;
    font-weight: 600;
    line-height: 1;
    letter-spacing: 0.42em;
    color: #8A6A2E;

    &::after {
      margin-left: -0.42em;
    }

    &::before,
    &::after {
      content: "";
      flex-shrink: 0;
      width: 44px;
      height: 1px;
      background: $ilp-gold-line;
    }
  }

  &__chip {
    order: 2;
    position: relative;
    display: inline-block;
    margin: 16px 0 0;
    padding: 6px 18px;
    background: $ilp-navy;
    font-family: $ilp-sans;
    font-size: 12px;
    font-weight: 700;
    line-height: 1.6;
    letter-spacing: 0.08em;
    color: #E2CB98;

    &::after {
      content: "";
      position: absolute;
      inset: 3px;
      border: 1px solid rgba(205, 174, 110, 0.6);
      pointer-events: none;
    }
  }

  &__title {
    order: 3;
    display: block;
    margin-top: 18px;
    font-family: $ilp-serif;
    font-size: 36px;
    font-weight: 600;
    line-height: 1.5;
    letter-spacing: 0.1em;
    color: $ilp-navy;
  }

  &__ornament {
    order: 4;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    margin-top: 14px;

    &::before,
    &::after {
      content: "";
      width: 40px;
      height: 1px;
      background: $ilp-gold-line;
    }
  }

  &__diamond {
    width: 7px;
    height: 7px;
    background: $ilp-gold;
    transform: rotate(45deg);
  }

  /* ---------- 即時埋入のカード ---------- */
  &__card {
    position: relative;
    margin-top: 72px;
    padding: 48px 60px 44px;
    background: #fff;
    box-shadow: 0 24px 48px rgba(42, 34, 80, 0.16);

    &::before {
      content: "";
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      height: 3px;
      background: $ilp-gold-line;
    }

    &::after {
      content: "";
      position: absolute;
      inset: 8px;
      border: 1px solid rgba(184, 151, 90, 0.35);
      pointer-events: none;
    }
  }

  &__card-label {
    display: flex;
    align-items: center;
    gap: 10px;
    font-family: $ilp-sans;
    font-size: 12.5px;
    font-weight: 700;
    line-height: 1.5;
    letter-spacing: 0.08em;
    color: #8A6A2E;

    &::before {
      content: "";
      width: 6px;
      height: 6px;
      background: $ilp-gold;
      transform: rotate(45deg);
    }
  }

  &__card-title {
    margin-bottom: 0;
    margin-top: 16px;
    font-family: $ilp-serif;
    font-size: 27px;
    font-weight: 600;
    line-height: 1.6;
    letter-spacing: 0.08em;
    color: $ilp-navy;
  }

  &__comment {
    display: grid;
    grid-template-columns: 86px minmax(0, 1fr);
    gap: 18px;
    align-items: start;
    margin-top: 18px;
  }

  &__avatar {
    margin: 0;
    text-align: center;
  }

  &__avatar-img {
    display: block;
    width: 86px;
    height: 86px;
    border: 2px solid #C2A061;
    border-radius: 50%;
    background-repeat: no-repeat;
    background-size: 150% auto;
    background-position: 50% 6%;
  }

  &__avatar-name {
    margin-top: 10px;
    font-family: $ilp-sans;
    font-size: 11px;
    font-weight: 700;
    line-height: 1.4;
    letter-spacing: 0.04em;
    white-space: nowrap;
    color: #B8975A;
  }

  &__bubble {
    position: relative;
    padding: 18px 24px;
    border: 1px solid rgba(194, 160, 97, 0.5);
    border-radius: 8px;
    background: #FBF7EE;
    font-family: $ilp-sans;
    font-size: 13.5px;
    font-weight: 400;
    line-height: 1.95;
    letter-spacing: 0.04em;
    color: $ilp-text;

    &::before {
      content: "";
      position: absolute;
      top: 20px;
      left: -7px;
      width: 12px;
      height: 12px;
      border-left: 1px solid rgba(194, 160, 97, 0.5);
      border-bottom: 1px solid rgba(194, 160, 97, 0.5);
      background: #FBF7EE;
      transform: rotate(45deg);
    }
  }

  // 比較の行
  &__compare {
    margin: 0;
    display: flex;
    flex-direction: column;
    gap: 14px;
    margin-top: 48px;
  }

  &__row {
    display: grid;
    grid-template-columns: 190px minmax(0, 1fr) 110px;
    gap: 20px;
    align-items: center;
  }

  &__row-label {
    font-family: $ilp-sans;
    font-size: 14px;
    font-weight: 700;
    line-height: 1.5;
    letter-spacing: 0.06em;
    color: $ilp-navy;
  }

  &__row.is-ours &__row-label {
    color: #8A6A2E;
  }

  // 箱と矢印：箱5つ＋矢印4つの9列グリッド（即時埋入の行は列をまたいで位置をそろえる）
  &__boxes {
    display: grid;
    grid-template-columns: 1fr 26px 1fr 26px 1fr 26px 1fr 26px 1fr;
    list-style: none;
  }

  &__box {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    height: 46px;
    padding: 0 8px;
    font-family: $ilp-sans;
    font-size: 13px;
    font-weight: 700;
    line-height: 1.3;
    letter-spacing: 0.04em;
    text-align: center;

    // 箱の右に矢印（最後の箱以外）
    &:not(:last-child)::after {
      content: "";
      position: absolute;
      top: 50%;
      left: 100%;
      width: 26px;
      height: 10px;
      transform: translateY(-50%);
      background:
        linear-gradient(#C2A061, #C2A061) left center / calc(100% - 2px) 1px no-repeat;
      clip-path: none;
    }

    &:not(:last-child)::before {
      content: "";
      position: absolute;
      top: 50%;
      left: calc(100% + 18px);
      width: 6px;
      height: 6px;
      border-top: 1px solid #C2A061;
      border-right: 1px solid #C2A061;
      transform: translateY(-50%) rotate(45deg);
    }

    // 1つ目：1列目、2つ目：3列目 … と1つおきに置く
    &:nth-child(1) { grid-column: 1; }
    &:nth-child(2) { grid-column: 3; }
    &:nth-child(3) { grid-column: 5; }
    &:nth-child(4) { grid-column: 7; }
    &:nth-child(5) { grid-column: 9; }

    &.is-surgery {
      background: $ilp-navy;
      color: #fff;
    }

    &.is-period {
      border: 1px solid #BEB6D2;
      background: #F5F3FA;
      color: $ilp-navy;
    }

    &.is-crown {
      border: 1px solid #D6BE8A;
      background: #FBF7EE;
      color: #8A6A2E;
    }

    &.is-gold {
      background: linear-gradient(155deg, #B3904E 0%, #CDAE6E 25%, #E2CB98 50%, #CFB173 75%, #B8964F 100%);
      color: $ilp-navy;
    }
  }

  // 即時埋入の行：抜歯＋埋入＝1〜3列、治癒期間＝5〜7列、被せ物＝9列
  &__row.is-ours &__box {
    &:nth-child(1) { grid-column: 1 / 4; }
    &:nth-child(2) { grid-column: 5 / 8; }
    &:nth-child(3) { grid-column: 9; }
  }

  &__result {
    display: flex;
    align-items: baseline;
    justify-content: center;
    gap: 4px;
    height: 46px;
    padding-top: 9px;
    border: 1px solid #D6BE8A;
    background: #fff;
    font-family: $ilp-serif;
    font-size: 14px;
    font-weight: 500;
    letter-spacing: 0.06em;
    color: $ilp-navy;

    // 回数の数字（Noto Serif JP）
    span {
      position: relative;
      top: 2px; // 数字だけ少し下げる（もっと下げる場合は数字を大きく）
      font-family: $ilp-serif;
      font-size: 24px;
      font-weight: 500;
      line-height: 1;
    }

    &.is-gold {
      border: 0;
      background: linear-gradient(155deg, #B3904E 0%, #CDAE6E 25%, #E2CB98 50%, #CFB173 75%, #B8964F 100%);
    }
  }

  /* ---------- STEP一覧 ---------- */
  &__nav {
    display: flex;
    align-items: stretch;
    gap: 18px;
    margin-top: 60px;
    list-style: none;

    li {
      position: relative;
      flex: 1;

      // 間の小さな矢印
      &:not(:last-child)::after {
        content: "";
        position: absolute;
        top: 50%;
        right: -12px;
        width: 6px;
        height: 6px;
        border-top: 1px solid #C2A061;
        border-right: 1px solid #C2A061;
        transform: translateY(-50%) rotate(45deg);
      }
    }
  }

  &__nav-link {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 6px;
    height: 92px;
    padding: 8px 4px;
    border: 1px solid #E3D3AE;
    background: #fff;
    text-align: center;
    text-decoration: none;
    color: $ilp-navy;
    transition: background-color 0.3s, color 0.3s;

    &:hover {
      background: #FBF7EE;
    }

    // 当院の特長のSTEP（紺）
    &.is-feature {
      border-color: $ilp-navy;
      background: $ilp-navy;
      color: #fff;

      .implant-flow__nav-num {
        color: #DCC28C;
      }
    }
  }

  &__nav-num {
    font-family: $ilp-en;
    font-size: 20px;
    font-style: italic;
    font-weight: 500;
    line-height: 1;
    color: $ilp-navy;
  }

  &__nav-text {
    font-family: $ilp-sans;
    font-size: 11.5px;
    font-weight: 700;
    line-height: 1.35;
    letter-spacing: 0.02em;
  }

  /* ---------- STEP 01〜08 ---------- */
  &__steps {
    position: relative;
    margin-top: 94px;
    list-style: none;

    // 左の縦線
    &::before {
      content: "";
      position: absolute;
      top: 44px;
      bottom: 0;
      left: 44px;
      width: 1px;
      background: rgba(194, 160, 97, 0.6);
    }
  }

  &__step {
    position: relative;
    display: grid;
    grid-template-columns: 88px 300px minmax(0, 1fr);
    gap: 40px;
    align-items: start;

    & + & {
      margin-top: 48px;
    }
  }

  &__step-num {
    position: relative;
    z-index: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 6px;
    width: 88px;
    height: 88px;
    border: 1px solid #C2A061;
    background: #FBF8F1;
    font-family: $ilp-en;
    font-size: 26px;
    font-style: italic;
    font-weight: 500;
    line-height: 1;
    color: #8A6A2E;
  }

  &__step-en {
    font-size: 10px;
    font-style: normal;
    font-weight: 600;
    letter-spacing: 0.3em;
    margin-right: -0.3em;
  }

  &__step-img {
    display: block;
    width: 300px;
    height: 200px;
    object-fit: cover;
  }

  &__step-body {
    padding-top: 12px;
  }

  &__step-title {
    margin: 0;
    font-family: $ilp-serif;
    font-size: 22px;
    font-weight: 600;
    line-height: 1.5;
    letter-spacing: 0.1em;
    color: $ilp-navy;
  }

  &__time {
    display: inline-flex;
    align-items: center;
    gap: 5px; // 時計と文字のあいだ
    margin-top: 12px;
    padding: 3px 12px 3px 8px; // 時計の左を少し詰める
    background: $ilp-gold-shine; // 見本：金のグラデーション
    font-family: $ilp-sans;
    font-size: 12px;
    font-weight: 700;
    line-height: 1.6;
    letter-spacing: 0.04em;
    color: $ilp-navy;
  }

  // 時計のアイコン
  // 時計のアイコン（画像：implant-lp-flow-clock.webp・紺 #2A2250）
  &__clock {
    position: relative;
    top: 0.5px; // 文字と高さがそろって見えるよう、少しだけ下げる
    display: block;
    flex-shrink: 0;
    width: 16px;
    height: 16px;
  }

  &__step-text {
    margin-top: 14px;
    font-family: $ilp-sans;
    font-size: 14px;
    font-weight: 400;
    line-height: 2;
    letter-spacing: 0.04em;
    color: #4F4A5E;
  }

  &__point {
    position: relative;
    display: flex;
    align-items: center;
    gap: 14px;
    margin-top: 16px;
    padding: 9px 16px;
    background: $ilp-navy;
    font-family: $ilp-sans;
    font-size: 13px;
    font-weight: 700;
    line-height: 1.5;
    letter-spacing: 0.04em;
    color: #fff;

    &::after {
      content: "";
      position: absolute;
      inset: 3px;
      border: 1px solid rgba(205, 174, 110, 0.55);
      pointer-events: none;
    }
  }

  &__point-label {
    flex-shrink: 0;
    font-family: $ilp-en;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.3em;
    color: #DCC28C;
  }

  /* ---------- タブレット ---------- */
  @media screen and (max-width: 1100px) {
    &__card {
      padding: 40px 32px 36px;
    }

    &__row {
      grid-template-columns: 1fr;
      gap: 8px;
    }

    &__result {
      width: 110px;
    }

    &__step {
      grid-template-columns: 88px 240px minmax(0, 1fr);
      gap: 28px;
    }

    &__step-img {
      width: 240px;
      height: 160px;
    }

    &__nav {
      flex-wrap: wrap;
      gap: 12px 18px;

      li {
        flex: 0 0 calc((100% - 18px * 3) / 4);
      }
    }
  }

  @media screen and (max-width: 900px) {
    &__step {
      grid-template-columns: 88px minmax(0, 1fr);
      gap: 20px;
    }

    &__step-img {
      grid-column: 2;
      width: 100%;
      max-width: 400px;
      height: auto;
      aspect-ratio: 3 / 2;
    }

    &__step-body {
      grid-column: 2;
      padding-top: 0;
    }
  }

  &__br-sp {
    display: none;
  }

  /* ---------- SP ---------- */
  @media screen and (max-width: 767px) {
    padding: 56px 0;
    // 見本：SPの背景 #FCFAF6 → #F6F0E5（背景画像なし）
    background: linear-gradient(180deg, #FCFAF6 0%, #F6F0E5 100%);

    &__inner {
      padding: 0 20px;
    }

    &__br-sp {
      display: inline;
    }

    // SPは チップ → 英字 → タイトル → ◆ の順
    &__chip {
      order: 0;
      margin-top: 0;
      padding: 8px 22px;
      font-size: 12.5px;
      font-weight: 500;
      line-height: 1.5;
      letter-spacing: 0.04em;
      color: #F1E9D6;

      &::after {
        display: none;
      }
    }

    &__en {
      order: 1;
      gap: 12px;
      margin-top: 14px;
      font-size: 13px;
      letter-spacing: 0.3em;

      &::after {
        margin-left: -0.3em;
      }

      &::before,
      &::after {
        width: 28px;
      }
    }

    &__title {
      order: 2;
      margin-top: 12px;
      font-size: 22px;
      letter-spacing: 0.06em;
    }

    &__ornament {
      order: 3;
    }

    // カード：上の金の線・内側の枠なし
    &__card {
      margin-top: 24px;
      padding: 16px 12px 18px;
      box-shadow: 0 14px 28px rgba(42, 34, 80, 0.16);

      &::before,
      &::after {
        display: none;
      }
    }

    // ● 当院なら、1度で完結型手術
    &__card-label {
      gap: 6px;
      font-size: 12px;

      &::before {
        width: 8px;
        height: 8px;
        border-radius: 50%;
        background: #8A6A2E;
        transform: none;
      }
    }

    &__card-title {
      margin-top: 4px;
      font-size: 16.5px;
      line-height: 1.55;
      letter-spacing: 0.02em;
    }

    &__comment {
      grid-template-columns: 66px minmax(0, 1fr);
      gap: 10px;
      margin-top: 8px;
    }

    &__avatar-img {
      width: 66px;
      height: 66px;
    }

    &__avatar-name {
      margin-top: 4px;
      font-size: 10px;
    }

    // 吹き出し：角は四角・しっぽなし
    &__bubble {
      padding: 12px 14px;
      border-radius: 0;
      font-size: 12px;
      line-height: 1.75;
      letter-spacing: 0.04em;

      &::before {
        display: none;
      }
    }

    // 比較：見出し（左）と手術◯回（右）、その下に箱を横1列
    &__compare {
      gap: 18px;
      margin: 22px 0 0;
    }

    &__row {
      grid-template-columns: minmax(0, 1fr) auto;
      gap: 8px 10px;
    }

    &__row-label {
      grid-column: 1;
      grid-row: 1;
      font-size: 13px;
    }

    &__result,
    &__result.is-gold {
      grid-column: 2;
      grid-row: 1;
      width: auto;
      height: auto;
      padding: 0;
      border: 0;
      background: none;
      font-size: 11px;
      color: $ilp-text;

      span {
        top: 1px;
        font-size: 22px;
        color: $ilp-navy;
      }
    }

    &__result.is-gold span {
      color: #8A6A2E;
    }

    &__boxes {
      grid-column: 1 / -1;
      grid-row: 2;
      grid-template-columns: repeat(5, minmax(0, 1fr));
      gap: 4px;
    }

    // 即時埋入：抜歯＋埋入（広め）／治癒期間／被せ物
    &__row.is-ours &__boxes {
      grid-template-columns: 2fr 1.15fr 1.15fr;
    }

    // 箱：小さく・矢印なし
    &__box,
    &__row.is-ours &__box {
      grid-column: auto !important;
      height: 30px;
      padding: 0 2px;
      font-size: 10.5px;
      font-weight: 700;
      letter-spacing: 0;

      &::before,
      &::after {
        display: none !important;
      }
    }

    &__box.is-period {
      border: 0;
      background: #F1EEF8;
      font-weight: 400;
      color: #6B6577;
    }

    &__box.is-crown {
      border: 1px solid #C9A764;
      background: #fff;
      font-weight: 400;
      color: $ilp-navy;
    }

    &__box.is-gold {
      background: linear-gradient(155deg, #CDAE6E 0%, #E2CB98 50%, #D9BC7E 100%);
    }

    // STEP一覧はSPでは出さない
    &__nav {
      display: none;
    }

    // STEP：左に番号（枠なし）と金の縦線、右に写真・文
    &__steps {
      margin-top: 28px;

      &::before {
        display: none;
      }
    }

    &__step {
      grid-template-columns: 32px minmax(0, 1fr);
      gap: 10px;

      & + & {
        margin-top: 22px;
      }

      // 番号の下の金の縦線
      &::before {
        content: "";
        position: absolute;
        top: 44px;
        bottom: 0;
        left: 11px;
        width: 1px;
        background: rgba(194, 160, 97, 0.7);
      }
    }

    &__step-num {
      align-items: flex-start;
      justify-content: flex-start;
      gap: 2px;
      width: auto;
      height: auto;
      border: 0;
      background: none;
      font-family: $ilp-serif;
      font-size: 20px;
      font-style: normal;
      font-weight: 600;
      color: $ilp-navy;
    }

    &__step-en {
      font-family: $ilp-en;
      font-size: 8px;
      letter-spacing: 0.2em;
      margin-right: 0;
      color: #8A6A2E;
    }

    &__step-img,
    &__step-body {
      grid-column: 2;
    }

    &__step-img {
      width: 100%;
      max-width: none;
      height: auto;
      aspect-ratio: 227 / 120;
    }

    &__step-body {
      margin-top: 0;
    }

    &__step-title {
      font-size: 15.5px;
      letter-spacing: 0.04em;
    }

    &__time {
      gap: 0;
      margin-top: 4px;
      padding: 1px 8px;
      font-size: 10.5px;
    }

    &__clock {
      display: none;
    }

    &__step-text {
      margin-top: 6px;
      font-size: 12px;
      line-height: 1.7;
    }

    // POINT：紺のグラデーションの帯（内側の枠なし）
    // 見本：文は Noto Sans JP 500／12px／行間22.2px／字間0.48px／白
    &__point {
      gap: 12px;
      margin-top: 10px;
      padding: 8px 14px;
      background: linear-gradient(180deg, #3A2F7A 0%, #1F1842 100%);
      font-size: 12px;
      font-weight: 500;
      line-height: 22.2px;
      letter-spacing: 0.04em;
      color: #fff;

      &::after {
        display: none;
      }
    }

    // 見本：POINT は Cormorant Garamond 700／12px／行間22.2px／字間1.68px
    &__point-label {
      font-size: 12px;
      font-weight: 700;
      line-height: 22.2px;
      letter-spacing: 0.14em;
    }
  }
}

/* ========================================
   インプラントLP：PRICE（インプラント治療の費用・料金表）
   ・背景：img/implant-lp-price-bg.webp（PHP の style="--price-bg"）
======================================== */

.implant-price {
  position: relative;
  padding: 56px 0 70px;
  background: #FBF8F2 var(--price-bg) center top / 100% 100% no-repeat;
  color: $ilp-text;

  &__inner {
    max-width: 1160px;
    margin: 0 auto;
    padding: 0 40px;
  }

  /* ---------- 見出し ---------- */
  &__head {
    text-align: center;
  }

  // h2（英字ラベル＋タイトル）
  &__heading {
    margin: 0;
    font-weight: 400;
  }

  &__en {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 16px;
    font-family: $ilp-en;
    font-size: 14px;
    font-weight: 600;
    line-height: 1;
    letter-spacing: 0.42em;
    color: #8A6A2E;

    &::after {
      margin-left: -0.42em;
    }

    &::before,
    &::after {
      content: "";
      flex-shrink: 0;
      width: 44px;
      height: 1px;
      background: $ilp-gold-line;
    }
  }

  &__title {
    display: block;
    margin-top: 18px;
    font-family: $ilp-serif;
    font-size: 36px;
    font-weight: 600;
    line-height: 1.5;
    letter-spacing: 0.08em;
    color: $ilp-navy;
  }

  &__ornament {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    margin-top: 12px;

    &::before,
    &::after {
      content: "";
      width: 40px;
      height: 1px;
      background: $ilp-gold-line;
    }
  }

  &__diamond {
    width: 7px;
    height: 7px;
    background: $ilp-gold;
    transform: rotate(45deg);
  }

  /* ---------- 院長コメント ---------- */
  &__comment {
    display: grid;
    grid-template-columns: 86px minmax(0, 1fr);
    gap: 18px;
    align-items: start;
    margin-top: 20px;
  }

  &__avatar {
    margin: 0;
    text-align: center;
  }

  &__avatar-img {
    display: block;
    width: 86px;
    height: 86px;
    border: 2px solid #C2A061;
    border-radius: 50%;
    background-repeat: no-repeat;
    background-size: 150% auto;
    background-position: 50% 6%;
  }

  &__avatar-name {
    margin-top: 10px;
    font-family: $ilp-sans;
    font-size: 11px;
    font-weight: 700;
    line-height: 1.4;
    letter-spacing: 0.04em;
    white-space: nowrap;
    color: #B8975A;
  }

  &__bubble {
    position: relative;
    padding: 18px 24px;
    border: 1px solid rgba(194, 160, 97, 0.5);
    border-radius: 8px;
    background: #FBF7EE;
    font-family: $ilp-sans;
    font-size: 13.5px;
    line-height: 1.95;
    letter-spacing: 0.04em;
    color: $ilp-text;

    &::before {
      content: "";
      position: absolute;
      top: 20px;
      left: -7px;
      width: 12px;
      height: 12px;
      border-left: 1px solid rgba(194, 160, 97, 0.5);
      border-bottom: 1px solid rgba(194, 160, 97, 0.5);
      background: #FBF7EE;
      transform: rotate(45deg);
    }
  }

  /* ---------- 総額＋月々 ---------- */
  &__summary {
    display: grid;
    grid-template-columns: 440px minmax(0, 1fr);
    margin-top: 40px;
    background: #fff;
    box-shadow: 0 20px 44px rgba(42, 34, 80, 0.12);
  }

  &__monthly {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 30px 20px;
    background: linear-gradient(160deg, #3A2F7A 0%, #2A2257 55%, #1E1840 100%);
    text-align: center;
    color: #fff;

    &::after {
      content: "";
      position: absolute;
      inset: 8px;
      border: 1px solid rgba(194, 160, 97, 0.55);
      pointer-events: none;
    }
  }

  &__monthly-label {
    font-family: $ilp-sans;
    font-size: 15px;
    font-weight: 700;
    letter-spacing: 0.1em;
    color: #DCC28C;
  }

  &__monthly-price {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-top: 4px;
    color: #DCC28C;

    // 大きな金額（<strong>）
    strong {
      font-family: $ilp-serif;
      font-size: 60px;
      font-weight: 500;
      line-height: 1.15;
      letter-spacing: 0.02em;

      @supports ((-webkit-background-clip: text) or (background-clip: text)) {
        background: linear-gradient(90deg, #C9A764 0%, #E2CB98 50%, #C4A363 100%);
        -webkit-background-clip: text;
        background-clip: text;
        color: transparent;
      }
    }

    // 月々・円〜
    small {
      font-family: $ilp-serif;
      font-size: 13px;
      font-weight: 500;
      color: #D9D4EA;
    }
  }

  &__monthly-note {
    margin-top: 4px;
    font-family: $ilp-sans;
    font-size: 14px;
    font-weight: 700;
    line-height: 1.6;
    letter-spacing: 0.04em;
  }

  &__total {
    position: relative;
    padding: 34px 40px 28px;

    &::after {
      content: "";
      position: absolute;
      inset: 8px;
      border: 1px solid rgba(184, 151, 90, 0.35);
      pointer-events: none;
    }
  }

  &__total-label {
    font-family: $ilp-sans;
    font-size: 14px;
    font-weight: 700;
    letter-spacing: 0.06em;
    color: $ilp-navy;
  }

  &__total-price {
    margin-top: 4px;
    font-family: $ilp-sans;
    font-size: 16px;
    color: $ilp-navy;

    // 大きな金額（<strong>）
    strong {
      margin-right: 8px;
      font-family: $ilp-serif;
      font-size: 54px;
      font-weight: 500;
      line-height: 1.15;
      letter-spacing: 0.02em;
    }

    small {
      font-size: 13px;
      color: #6B6577;
    }
  }

  &__total-break {
    margin-top: 2px;
    font-family: $ilp-sans;
    font-size: 12.5px;
    line-height: 1.6;
    color: #6B6577;
  }

  &__tags {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: 14px;
    list-style: none;

    li {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 5px 12px;
      border: 1px solid #D6BE8A;
      background: #FBF7EE;
      font-family: $ilp-sans;
      font-size: 12px;
      font-weight: 700;
      letter-spacing: 0.02em;
      color: $ilp-navy;
    }

    img {
      display: block;
      width: 14px;
      height: 14px;
    }
  }

  &__total-note {
    margin-top: 14px;
    font-family: $ilp-sans;
    font-size: 12px;
    color: #6B6577;
  }

  /* ---------- 小見出し（左に金の線） ---------- */
  &__h3 {
    position: relative;
    margin-top: 40px;
    padding-left: 18px;
    font-family: $ilp-serif;
    font-size: 24px;
    font-weight: 600;
    line-height: 1.5;
    letter-spacing: 0.1em;
    color: $ilp-navy;

    &::before {
      content: "";
      position: absolute;
      top: 0.15em;
      bottom: 0.15em;
      left: 0;
      width: 4px;
      background: linear-gradient(180deg, #C2A061 0%, #E2CB98 50%, #C4A363 100%);
    }
  }

  &__h3-sub {
    margin-top: 12px;
    font-family: $ilp-sans;
    font-size: 13.5px;
    line-height: 1.7;
    letter-spacing: 0.04em;
    color: $ilp-text;
  }

  /* ---------- 保証 ---------- */
  &__guarantee {
    position: relative;
    margin-top: 22px;
    padding: 30px 40px 26px;
    background: #fff;
    box-shadow: 0 18px 40px rgba(42, 34, 80, 0.09);

    &::after {
      content: "";
      position: absolute;
      inset: 6px;
      border: 1px solid rgba(184, 151, 90, 0.35);
      pointer-events: none;
    }
  }

  &__guarantee-main {
    display: grid;
    grid-template-columns: 400px minmax(0, 1fr);
    gap: 40px;
    align-items: center;
  }

  &__guarantee-img {
    display: block;
    width: 100%;
    height: auto;
  }

  &__guarantee-list {
    display: flex;
    flex-direction: column;
    gap: 14px;
    margin: 0;
  }

  &__guarantee-item {
    display: grid;
    grid-template-columns: 120px minmax(0, 1fr);
    gap: 22px;
    align-items: center;
    padding: 18px 20px;
    border: 1px solid #E3D3AE;
    background: #FBF7EE;

    dd {
      margin: 0;
    }
  }

  // 保証◯年（保証・数字・年をまとめて上下中央に）
  &__guarantee-badge {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 2px;
    width: 120px;
    height: 96px;
    background: $ilp-navy;

    &::after {
      content: "";
      position: absolute;
      inset: 4px;
      border: 1px solid rgba(205, 174, 110, 0.55);
      pointer-events: none;
    }

    small {
      font-family: $ilp-sans;
      font-size: 12px;
      font-weight: 400;
      line-height: 1.4;
      letter-spacing: 0.08em;
      color: #DCC28C;
    }
  }

  // 数字＋年（どちらも白）
  &__guarantee-years {
    display: flex;
    align-items: baseline;
    gap: 3px;
    font-family: $ilp-serif;
    font-size: 15px;
    font-weight: 500;
    line-height: 1;
    color: #fff;

    span {
      font-size: 40px;
      line-height: 1;
    }
  }

  &__guarantee-name {
    font-family: $ilp-serif;
    font-size: 19px;
    font-weight: 600;
    line-height: 1.5;
    letter-spacing: 0.06em;
    color: $ilp-navy;
  }

  &__guarantee-text {
    margin-top: 6px;
    font-family: $ilp-sans;
    font-size: 13px;
    line-height: 1.7;
    color: $ilp-text;
  }

  &__guarantee-note {
    small {
      font-size: inherit;
    }

    margin-top: 28px;
    font-family: $ilp-sans;
    font-size: 12px;
    color: #6B6577;
  }

  /* ---------- 料金表 ---------- */
  &__table-wrap {
    margin-top: 22px;
    box-shadow: 0 18px 40px rgba(42, 34, 80, 0.09);
  }

  &__table {
    width: 100%;
    border-collapse: collapse;
    background: #fff;

    thead th {
      padding: 13px 24px;
      background: $ilp-navy;
      font-family: $ilp-sans;
      font-size: 13px;
      font-weight: 700;
      line-height: 1.5;
      letter-spacing: 0.06em;
      text-align: left;
      color: #fff;

      &.is-guarantee {
        width: 140px;
        text-align: center;
      }

      &.is-price {
        width: 200px;
        text-align: center;
      }
    }

    tbody tr {
      border-bottom: 1px solid #ECE6DA;

      &:nth-child(even) {
        background: #FCFAF5;
      }

      &:last-child {
        border-bottom: 0;
      }
    }

    tbody th,
    tbody td {
      padding: 20px 24px;
      vertical-align: middle;
    }

    tbody th {
      text-align: left;
    }

    td.is-guarantee {
      text-align: center;
      font-family: $ilp-sans;
      color: #8C8796;
    }

    td.is-price {
      text-align: right;
      white-space: nowrap;
      color: $ilp-navy;

      small {
        font-family: $ilp-sans;
        font-size: 11px;
        color: #6B6577;
      }
    }
  }

  &__item-name {
    display: block;
    font-family: $ilp-serif;
    font-size: 16px;
    font-weight: 600;
    line-height: 1.5;
    letter-spacing: 0.08em;
    color: $ilp-navy;
  }

  &__item-desc {
    display: block;
    margin-top: 6px;
    font-family: $ilp-sans;
    font-size: 12.5px;
    font-weight: 400;
    line-height: 1.8;
    letter-spacing: 0.02em;
    color: #5C566B;
  }

  &__badge {
    display: inline-block;
    padding: 2px 10px;
    border: 1px solid #C2A061;
    background: #FBF7EE;
    font-size: 12px;
    font-weight: 700;
    color: $ilp-navy;
  }

  &__yen {
    margin-right: 2px;
    font-family: $ilp-serif;
    font-size: 22px;
    font-weight: 500;
    letter-spacing: 0.02em;
  }

  /* ---------- お支払い方法 ---------- */
  &__methods {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 8px 10px;
    margin-top: 16px;

    ul {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
      list-style: none;
    }

    li {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 5px 14px;
      border: 1px solid #D6BE8A;
      background: #fff;
      font-family: $ilp-sans;
      font-size: 12.5px;
      font-weight: 700;
      color: $ilp-navy;

      // カードのアイコン（img/implant-lp-price-icon-card.webp）
      img {
        display: block;
        flex-shrink: 0;
        width: 14px;
        height: 14px;
      }
    }
  }

  &__methods-label {
    font-family: $ilp-sans;
    font-size: 13px;
    color: $ilp-text;
  }

  /* ---------- 月々のお支払い表 ---------- */
  &__table--plan {
    table-layout: fixed;

    thead th {
      text-align: center;

      &.is-highlight {
        background: #1E1840;
      }
    }

    tbody th {
      width: 20%;
    }

    tbody td {
      text-align: center;

      &.is-highlight {
        background: #F2F0F7;
      }
    }
  }

  &__plan-total {
    display: block;
    margin-top: 4px;
    font-family: $ilp-serif;
    font-size: 13px;
    color: #8A6A2E;
  }

  &__plan-price {
    display: block;
    font-family: $ilp-serif;
    font-size: 19px;
    font-weight: 500;
    line-height: 1.4;
    color: $ilp-navy;
  }

  &__plan-first {
    display: block;
    font-family: $ilp-sans;
    font-size: 11px;
    color: #6B6577;
  }

  /* ---------- 注記 ---------- */
  &__notes {
    small {
      font-size: inherit;
    }

    margin-top: 28px;
    padding: 24px 32px;
    background: rgba(243, 237, 224, 0.6);
    list-style: none;

    li {
      font-family: $ilp-sans;
      font-size: 12.5px;
      line-height: 2.1;
      letter-spacing: 0.02em;
      color: #5C566B;

      &::before {
        content: "※ ";
      }
    }
  }

  /* ---------- タブレット ---------- */
  @media screen and (max-width: 1100px) {
    &__summary {
      grid-template-columns: 360px minmax(0, 1fr);
    }

    &__monthly-price strong {
      font-size: 48px;
    }

    &__total {
      padding: 28px 28px 24px;
    }

    &__total-price strong {
      font-size: 44px;
    }

    &__guarantee-main {
      grid-template-columns: 320px minmax(0, 1fr);
      gap: 28px;
    }
  }

  @media screen and (max-width: 900px) {
    &__summary,
    &__guarantee-main {
      grid-template-columns: 1fr;
    }

    &__guarantee-img {
      max-width: 480px;
      margin: 0 auto;
    }
  }

  // SP用の表・改行はPCでは出さない
  &__table-wrap--plan-sp,
  &__badge-sp,
  &__br-sp {
    display: none;
  }

  /* ---------- SP ---------- */
  @media screen and (max-width: 767px) {
    padding: 56px 0;
    // 見本：SPの背景 #FCFAF6 → #F6F0E5（背景画像なし）
    background: linear-gradient(180deg, #FCFAF6 0%, #F6F0E5 100%);

    &__inner {
      padding: 0 20px;
    }

    &__br-sp {
      display: inline;
    }

    &__en {
      gap: 12px;
      font-size: 13px;
      letter-spacing: 0.3em;

      &::after {
        margin-left: -0.3em;
      }

      &::before,
      &::after {
        width: 28px;
      }
    }

    // インプラント治療の／費用・料金表
    &__title {
      margin-top: 12px;
      font-size: 22px;
      line-height: 1.55;
      letter-spacing: 0.06em;
    }

    &__comment {
      grid-template-columns: 66px minmax(0, 1fr);
      gap: 12px;
      margin-top: 22px;
    }

    &__avatar-img {
      width: 66px;
      height: 66px;
    }

    &__avatar-name {
      font-size: 10px;
    }

    // 吹き出し：角は四角
    &__bubble {
      padding: 12px 14px;
      border-radius: 0;
      font-size: 12.5px;
      line-height: 1.75;
    }

    &__summary {
      margin-top: 22px;
    }

    // 見本：パディング16px／紺のグラデーション（#3A2F7A → #2A2250 → #1E1840）／内側に金の細い枠
    &__monthly {
      padding: 16px;
      background: linear-gradient(180deg, #3A2F7A 0%, #2A2250 50%, #1E1840 100%);

      &::after {
        display: block;
        inset: 8px;
      }
    }

    &__monthly-label {
      font-size: 13px;
    }

    &__monthly-price {
      justify-content: center;
      gap: 4px;
      margin-top: 0;

      strong {
        font-size: 40px;
      }

      small {
        font-size: 14px;
        color: #fff;
      }
    }

    &__monthly-note {
      margin-top: 0;
      font-size: 12px;
      line-height: 1.55;
    }

    &__total {
      padding: 16px 14px 18px;

      &::after {
        display: none;
      }
    }

    &__total-label {
      font-size: 13px;
    }

    &__total-price strong {
      margin-right: 4px;
      font-size: 34px;
    }

    &__total-break {
      font-size: 11px;
      line-height: 1.6;
    }

    // タグ：小さく・アイコンなし
    &__tags {
      gap: 6px;
      margin-top: 10px;

      li {
        gap: 0;
        padding: 3px 8px;
        font-size: 11px;

        img {
          display: none;
        }
      }
    }

    &__total-note {
      font-size: 11px;
    }

    &__h3 {
      margin-top: 40px;
      padding-left: 14px;
      font-size: 18px;
      line-height: 1.55;
      letter-spacing: 0.04em;
    }

    &__h3-sub {
      font-size: 12.5px;
      line-height: 1.75;
    }

    &__guarantee {
      padding: 14px 12px 16px;
    }

    &__guarantee-item {
      grid-template-columns: 62px minmax(0, 1fr);
      gap: 12px;
      padding: 10px 12px;
    }

    &__guarantee-badge {
      width: 62px;
      height: 56px;

      &::after {
        inset: 3px;
      }

      small {
        font-size: 9.5px;
      }
    }

    &__guarantee-years {
      font-size: 11px;

      span {
        font-size: 22px;
      }
    }

    &__guarantee-name {
      font-size: 15px;
    }

    &__guarantee-text {
      font-size: 11.5px;
      line-height: 1.6;
    }

    &__guarantee-note {
      margin-top: 12px;
      font-size: 11px;
    }

    // 料金表（基本料金・骨造成）：白い箱の中に、
    // 1行目「治療名 …… 金額」／2行目 説明／3行目 保証タグ
    &__table--basic,
    &__table--bone {
      display: block;
      padding: 4px 16px;

      thead {
        display: none;
      }

      tbody {
        display: block;
      }

      tbody tr {
        display: grid;
        grid-template-columns: minmax(0, 1fr) auto;
        column-gap: 10px;
        align-items: start;
        padding: 18px 0;
        background: none !important;

        & + tr {
          border-top: 1px solid #ECE6DA;
        }
      }

      tbody th,
      tbody td {
        height: auto;
        padding: 0;
        border: 0;
        background: none;
      }

      // th（治療名＋説明）をほどいて並べる
      tbody th {
        display: contents;
      }

      .implant-price__item-name {
        grid-column: 1;
        grid-row: 1;
      }

      .implant-price__item-desc {
        grid-column: 1 / -1;
        grid-row: 2;
      }

      td.is-price {
        grid-column: 2;
        grid-row: 1;
        white-space: nowrap;
        text-align: right;
      }

      td.is-guarantee {
        grid-column: 1 / -1;
        grid-row: 3;
        margin-top: 8px;
        text-align: left;

        &.is-empty {
          display: none;
        }
      }
    }

    &__badge-sp {
      display: inline;
    }

    &__item-name {
      font-size: 15px;
      line-height: 1.5;
      letter-spacing: 0.04em;
    }

    &__item-desc {
      margin-top: 6px;
      font-size: 12px;
      line-height: 1.65;
    }

    &__yen {
      font-size: 20px;
      line-height: 1.2;
    }

    // お支払い方法
    &__methods {
      flex-wrap: wrap;
      gap: 8px 6px;
    }

    &__methods ul {
      display: contents;
    }

    &__methods li {
      padding: 3px 10px;
      font-size: 11.5px;

      img {
        display: none;
      }
    }

    // お支払い例：PCの表を隠して、SP用の表（回数を縦に）を出す
    &__table-wrap:has(.implant-price__table--plan) {
      display: none;
    }

    &__table-wrap--plan-sp {
      display: block;
      margin-top: 14px;
    }

    &__table--plan-sp {
      table-layout: fixed;

      th,
      td {
        height: auto;
        padding: 10px 6px;
        border-bottom: 1px solid #ECE6DA;
        text-align: center;
        vertical-align: middle;
      }

      // 見本：見出しは中央揃え・上下にゆとり
      thead th,
      thead th:first-child {
        padding: 16px 2px;
        text-align: center !important;
        background: $ilp-navy;
        font-family: $ilp-sans;
        font-size: 11.5px;
        font-weight: 700;
        line-height: 1.5;
        letter-spacing: 0;
        white-space: nowrap;
        color: #fff;

        &:first-child {
          width: 29%;
        }
      }

      // 542,300円（ゴシック・金）
      thead .implant-price__plan-total {
        display: block;
        margin-top: 2px;
        font-family: $ilp-sans;
        font-size: 10.5px;
        font-weight: 500;
        line-height: 1.4;
        letter-spacing: 0.02em;
        text-align: center;
        color: #DCC28C;
      }

      // 見本：Noto Sans JP 500／12px／行間18px／字間0.42px／#5C566B（1行）
      tbody th {
        padding: 10px 4px 10px 8px;
        background: #F8F5EE;
        font-family: $ilp-sans;
        font-size: 12px;
        font-weight: 500;
        line-height: 18px;
        letter-spacing: 0.035em;
        white-space: nowrap;
        text-align: left;
        color: #5C566B;
      }

      tbody td {
        background: #fff;
      }

      // 24回の行は薄い紫で強調
      // 24回の行：金額の箱だけ薄い紫（回数の欄はほかの行と同じ）
      tr.is-highlight td {
        background: #F1EEF8;
        font-weight: 700;
      }

      tbody tr:last-child th,
      tbody tr:last-child td {
        border-bottom: 0;
      }

      .implant-price__plan-price {
        font-size: 16px;
        white-space: nowrap;
      }

      .implant-price__plan-first {
        font-size: 10px;
      }
    }

    &__notes {
      margin-top: 24px;
      padding: 16px 14px;

      li {
        font-size: 11px;
        line-height: 1.75;
      }
    }
  }
}

/* ========================================
   インプラントLP：FAQ（インプラント治療のよくあるご質問）
   ・開閉は implant-lp.js の initFaq（1つ開くと、ほかは閉じる）
======================================== */

.implant-faq {
  position: relative;
  padding: 60px 0 66px;
  background:
    radial-gradient(ellipse 40% 50% at 0% 100%, rgba(226, 214, 246, 0.6) 0%, rgba(226, 214, 246, 0) 100%),
    radial-gradient(ellipse 35% 45% at 100% 0%, rgba(226, 230, 250, 0.7) 0%, rgba(226, 230, 250, 0) 100%),
    linear-gradient(180deg, #FCFBFF 0%, #F4F1FA 100%);
  color: $ilp-text;

  &__inner {
    max-width: 1160px;
    margin: 0 auto;
    padding: 0 40px;
  }

  /* ---------- 見出し ---------- */
  &__head {
    text-align: center;
  }

  // h2（英字ラベル＋タイトル）
  &__heading {
    margin: 0;
    font-weight: 400;
  }

  &__br-sp {
    display: none;
  }

  &__en {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 16px;
    font-family: $ilp-en;
    font-size: 14px;
    font-weight: 600;
    line-height: 1;
    letter-spacing: 0.42em;
    color: #8A6A2E;

    &::after {
      margin-left: -0.42em;
    }

    &::before,
    &::after {
      content: "";
      flex-shrink: 0;
      width: 44px;
      height: 1px;
      background: $ilp-gold-line;
    }
  }

  &__title {
    display: block;
    margin-top: 20px;
    font-family: $ilp-serif;
    font-size: 34px;
    font-weight: 600;
    line-height: 1.5;
    letter-spacing: 0.08em;
    color: $ilp-navy;
  }

  &__ornament {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    margin-top: 14px;

    &::before,
    &::after {
      content: "";
      width: 40px;
      height: 1px;
      background: $ilp-gold-line;
    }
  }

  &__diamond {
    width: 7px;
    height: 7px;
    background: $ilp-gold;
    transform: rotate(45deg);
  }

  /* ---------- 質問の一覧 ---------- */
  &__list {
    display: flex;
    flex-direction: column;
    gap: 12px;
    margin-top: 32px;
  }

  &__item {
    position: relative;
    background: #fff;
    box-shadow: 0 10px 24px rgba(42, 34, 80, 0.05);
    transition: box-shadow 0.5s;

    // 開いているときは、内側の金の細い枠と強めの影
    &.is-open {
      box-shadow: 0 18px 36px rgba(42, 34, 80, 0.14);

