  &__en {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 16px;
    font-family: $ilp-en;
    font-size: 14px;
    font-weight: 600;
    line-height: 1;
    letter-spacing: 0.42em;
    color: #8A6A2E;

    &::after {
      margin-left: -0.42em;
    }

    &::before,
    &::after {
      content: "";
      flex-shrink: 0;
      width: 44px;
      height: 1px;
      background: $ilp-gold-line;
    }
  }

  &__title {
    display: block;
