    font-size: 14px;
    font-weight: 400;
    line-height: 1.8;
    letter-spacing: 0.06em;
    color: #5C566B;
  }

  /* ---------- カード ---------- */
  &__list {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 32px 20px;
    margin-top: 32px;
    list-style: none;
  }

  &__item {
    display: flex;
    flex-direction: column;
  }

  // 動画の枠（16:9）
  &__frame {
    position: relative;
    overflow: hidden;
    aspect-ratio: 16 / 9;
    border-radius: 4px;
    background: #2A2250;
    box-shadow: 0 10px 22px rgba(42, 34, 80, 0.14);

    iframe {
      position: absolute;
      inset: 0;
      z-index: 3;
      width: 100%;
      height: 100%;
      border: 0;
    }
  }

  &__thumb {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  // 再生ボタン：白い丸に紺の三角（全面を押せるように）
  &__play {
    position: absolute;
    inset: 0;
    z-index: 2;
    width: 100%;
    height: 100%;
    padding: 0;
    border: 0;
    background: none;
    cursor: pointer;

    &::before {
      content: "";
      position: absolute;
      top: 50%;
      left: 50%;
      width: 54px;
      height: 54px;
      border-radius: 50%;
      background: rgba(255, 255, 255, 0.9);
      box-shadow: 0 6px 16px rgba(20, 14, 40, 0.25);
      transform: translate(-50%, -50%);
      transition: transform 0.3s;
    }

    &:hover::before {
      transform: translate(-50%, -50%) scale(1.08);
    }
  }

  &__play-icon {
    position: absolute;
    top: 50%;
    left: 50%;
    width: 14px;
    height: 16px;
    background: $ilp-navy;
    clip-path: polygon(0 0, 100% 50%, 0 100%);
    transform: translate(-35%, -50%);
  }

  &__frame.is-playing &__play,
  &__frame.is-playing &__thumb {
    display: none;
  }

  // 見本：Noto Sans JP 700・紺
  &__item-title {
    margin: 16px 0 0;
    font-family: $ilp-sans;
    font-size: 15px;
    font-weight: 700;
    line-height: 1.75;
    letter-spacing: 0.06em;
    color: $ilp-navy;
  }

  &__link {
    align-self: flex-start;
    margin-top: 8px;
    font-family: $ilp-sans;
    font-size: 13px;
    font-weight: 400;
    line-height: 1.6;
    letter-spacing: 0.04em;
    color: #8A6A2E;
    text-decoration: none;
    transition: opacity 0.3s;

    &:hover {
      opacity: 0.7;
    }
  }

  /* ---------- タブレット ---------- */
  @media screen and (max-width: 900px) {
    &__list {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
  }

  /* ---------- SP ---------- */
  @media screen and (max-width: 767px) {
    padding: 40px 0 48px;

    &__inner {
      padding: 0 20px;
    }

    &__br-sp {
      display: inline;
    }

    &__en {
      gap: 12px;
      font-size: 13px;
      letter-spacing: 0.3em;

      &::after {
        margin-left: -0.3em;
      }

      &::before,
      &::after {
        width: 28px;
      }
    }

    // 動画でわかる／インプラント治療
    &__title {
      margin-top: 12px;
      font-size: 22px;
      line-height: 1.6;
      letter-spacing: 0.06em;
    }

    &__lead {
      margin-top: 8px;
      font-size: 12.5px;
      line-height: 1.7;
      letter-spacing: 0.02em;
    }

    &__list {
      grid-template-columns: 1fr;
      gap: 26px;
      margin-top: 22px;
    }

    &__play::before {
      width: 46px;
      height: 46px;
    }

    &__play-icon {
      width: 12px;
      height: 14px;
    }

    &__item-title {
      margin-top: 12px;
      font-size: 14px;
      line-height: 1.7;
      letter-spacing: 0.04em;
    }

    &__link {
      margin-top: 4px;
      font-size: 12px;
    }
  }
}

